"""Independent same-P1 numerical rejection audit, no new solver/update.
Rebuild ONE saved QP coefficients and verify physical freeY moment defect.
"""
import sys,json,shutil,time
import numpy as np
from scipy import sparse
import osqp
from skfem import MeshTet,Basis,ElementVector,ElementTetP1,asm
from skfem.models.elasticity import linear_elasticity,lame_parameters
from baseline_registry import ROOT,REPO,ref,dump
from primary_corotated_support import Support

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated/primaryP1_finite_increment2/summary.json';s=json.loads(src.read_text());a=dict(np.load(REPO/s['source_field']['path']));p=np.load(REPO/s['predictor_npz']['path']);trial=np.load(REPO/s['trial_field_npz']['path']);loads=json.loads((REPO/s['trial_loads_json']['path']).read_text());local=json.loads((REPO/s['source']['path']).read_text());field=np.load(REPO/local['output']['path']);model=Support(a,local['elastic_bodies']);u=a['u_mm'];N=len(u);Kparts=[]
 for name in local['elastic_bodies']:
  X=a[name+'_points_mm'];o=int(a[name+'_offset']);current=X+u[o:o+3*len(X)].reshape(-1,3);t=a[name+'_tetra'];mesh=MeshTet(current.T,t.T);el=ElementVector(ElementTetP1());lam,mu=lame_parameters(float(a[name+'_E_MPa']),float(a[name+'_nu']));K=sparse.csr_matrix((3*len(X),3*len(X)))
  # Independent chunk size; same declared currentgeometry linear metric.
  for first in range(0,len(t),10000):K+=asm(linear_elasticity(lam,mu),Basis(mesh,el,intorder=2,elements=np.arange(first,min(first+10000,len(t)))))
  Kparts.append(K)
 K=sparse.block_diag(Kparts+[sparse.csr_matrix((6,6))],format='csc');K=sparse.triu(K,format='csc')+sparse.triu(K,1,format='csc').T;ks=a['bolt_k_N_mm'];B=sparse.csr_matrix(np.vstack([model.connectors(u,np.eye(14)[j])[1] for j in range(14)]));Q=sparse.csr_matrix(a['gauge_Q']);geo=json.loads((ROOT/'validation/integrated/primaryP1_surface_geometry3/summary.json').read_text());g=np.load(REPO/geo['output']['path']);J=sparse.csr_matrix((g['J_data'],g['J_indices'],g['J_indptr']),shape=tuple(g['J_shape']));ext,_=model.connectors(u);
 ext,_=model.connectors(u);ks=a['bolt_k_N_mm'];P=sparse.block_diag([K,sparse.diags(ks)],format='csc');q=np.r_[field['elastic_force_N']-p['source_applied_force_N'],np.zeros(14)];A=sparse.vstack([sparse.hstack([J,sparse.csr_matrix((2169,14))]),sparse.hstack([Q,sparse.csr_matrix((Q.shape[0],14))]),sparse.hstack([-B,sparse.eye(14)]),sparse.hstack([sparse.csr_matrix((14,N)),sparse.eye(14)])],format='csc');lo=np.r_[-p['source_gaps_mm'],a['gauge_targets_mm']-Q@u,ext,np.zeros(14)];hi=np.r_[np.full(2169,np.inf),a['gauge_targets_mm']-Q@u,np.full(28,np.inf)]

 source=ROOT/'validation/integrated/primaryP1_cone_conditioning1/summary.json';r=json.loads(source.read_text());sc=np.load(REPO/r['scales']['path']);v=np.load(REPO/r['output']['path']);D=sc['D'];E=sc['E'];x=np.r_[v['increment_mm'],v['tension_extension_mm']];y=v['physical_dual'];g=P@x+q+A.T@y;sl=A@x-lo;eq=slice(2169,2169+Q.shape[0]);primal=max(float(np.max(np.maximum(-sl,0))),float(np.max(abs(sl[eq]))));dual=float(np.max(abs(g)));mask=np.ones(len(y),bool);mask[eq]=False;comp=float(np.max(abs(sl[mask]*y[mask])));sign=float(np.max(np.maximum(y[mask],0)))
 # Root_free_Y is the original seventh gauge row, from original source labels.
 original=json.loads((ROOT/'validation/integrated/primaryP1_front_h5_2/summary.json').read_text());labels=original['gauge_labels'];ri=labels.index('Root_free_Y');mi=labels.index('Motor_free_Y');assert ri==6
 # Add ONE unpenalized coordinate gamma to the existing equality, Q du-e_r gamma=target.
 # Stationarity of gamma imposes y_Root=0; Motor equality and every other row remain identical.
 c=np.zeros(A.shape[0]);c[2169+ri]=-1;Aaug=sparse.hstack([A,sparse.csc_matrix(c[:,None])],format='csc');free=np.zeros(N);b=model.bodies['F0_ROOT_BACK'];o=b['offset'];free[o+1:o+3*len(b['X']):3]=1;response=Q@free
 h=.00016055476979;delta=np.r_[h*free,np.zeros(14)];gamma=float(Q[ri]@delta[:N]);aug=np.r_[delta,gamma];resp=Aaug@aug;physical=A@delta;nonroot=np.arange(A.shape[0])!=2169+ri;rootcancel=float(abs(resp[2169+ri]));unchanged=float(np.max(abs(resp[nonroot]-physical[nonroot])));motorresponse=float(abs(resp[2169+mi]));dual_gamma=float(Aaug[:,-1].T@y)
 ytest=np.zeros(A.shape[0]);ytest[2169+ri]=.001;bad=float(Aaug[:,-1].T@ytest);wrongcol=np.zeros(A.shape[0]);wrongcol[2169+mi]=-1;wronggamma=float(abs((A@sparse.csr_matrix(delta[:,None])).toarray().ravel()[2169+ri]+wrongcol[2169+ri]*gamma))
 tests=dict(primal_reproduced=abs(primal-r['physical_primal_mm'])<1e-10,dual_reproduced=abs(dual-r['physical_dual_N'])<1e-8,all_slacks_reproduced=float(np.max(abs(sl-v['physical_slack_mm'])))<1e-10,stationarity_reproduced=float(np.max(abs(g-v['stationarity_N'])))<1e-8,complementarity_reproduced=abs(comp-r['physical_complementarity_Nmm'])<1e-10,positive_scaling=bool(min(D.min(),E.min())>0),original_labels_confirmed=ri==6 and mi==7,Root_coordinate_not_free_at_fixed_target=abs(response[ri]-1)<1e-12,augmented_Root_coordinate_identity=rootcancel<1e-12,all_other_rows_unchanged=unchanged<1e-12,MotorY_semantics_unchanged=motorresponse<1e-12,nonzero_Root_gauge_force_rejected=abs(bad+.001)<1e-12,wrong_Motor_coordinate_control=wronggamma>1e-5)
 result=dict(status='ACTUAL_P1_CONDITIONING_AND_ROOTY_COORDINATE_AUDIT_PASS' if all(tests.values()) else 'ACTUAL_P1_CONDITIONING_AND_ROOTY_COORDINATE_AUDIT_FAIL',candidate=s['candidate'],source=ref(source),source_field=s['source_field'],verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in tests.items()},physical_primal_mm=primal,physical_dual_N=dual,physical_complementarity_Nmm=comp,physical_dual_sign_N=sign,linear_KKT_qualified=primal<1e-8 and dual<1e-8 and sign<1e-8 and comp<1e-8,original_gauge_labels=labels,original_RootY_gauge_index=ri,original_MotorY_gauge_index=mi,original_RootY_target_mm=float(a['gauge_targets_mm'][ri]),RootY_augmented_gamma_mm=gamma,RootY_augmented_equality_error_mm=rootcancel,other_rows_change_error_mm=unchanged,MotorY_coordinate_response_mm=motorresponse,conditioned_candidate_gamma_stationarity_N=dual_gamma,zeroGammaHessian=True,all2169contact_inequalities_preserved=True,all14branches_preserved=True,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start,limitations=['Independent chunkassembly audits actual original P1 problem. Exact RootY coordinate identity is NOT a solved augmented KKT or nonlinear equilibrium.','Gamma has zero objective; its stationarity MUST require negligible Root gauge reaction. Fixing gamma or retaining Root gauge support under attachedY loads would hide a physical reaction. MotorY/original other gauge semantics preserved.','Cone scaling is exact but does not remove linear KKT convergence failure. No extra QP, physical update or Base cancellation in this verifier.'])
 dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if all(tests.values()) else 2)
if __name__=='__main__':main()
